<script lang="ts">
  import { goto } from '$app/navigation'
  import { resolve } from '$app/paths'
  import type { Person, PrivateMessageView } from '$lib/api/types'
  import { profile } from '$lib/app/auth'

  import UserAutocomplete from '$lib/feature/user/UserAutocomplete.svelte'
  import Avatar from '$lib/ui/generic/Avatar.svelte'
  import Fixate from '$lib/ui/generic/Fixate.svelte'
  import Skeleton from '$lib/ui/generic/Skeleton.svelte'
  import Placeholder from '$lib/ui/info/Placeholder.svelte'
  import { CommonList, Header, Pageination } from '$lib/ui/layout'
  import { publishedToDate } from '$lib/ui/util/date'
  import { Button, Modal } from 'mono-svelte'
  import RelativeDate from 'mono-svelte/util/RelativeDate.svelte'
  import {
    ChatBubbleOvalLeftEllipsis,
    Icon,
    Inbox,
  } from 'svelte-hero-icons/dist'
  import { expoOut } from 'svelte/easing'
  import { SvelteSet } from 'svelte/reactivity'
  import { fly } from 'svelte/transition'

  interface ConversationPreview {
    user: Person
    message: {
      date: Date
      last_sender: number
      content: string
    }
  }

  function getOtherPartyId(message: PrivateMessageView): number {
    return message.creator.id == profile.current.user?.local_user_view.person.id
      ? message.recipient.id
      : message.creator.id
  }

  function filterDuplicates<T, K>(array: T[], predicate: (item: T) => K): T[] {
    const seen = new SvelteSet()
    return array.filter((element) => {
      const value = predicate(element)
      if (seen.has(value)) {
        return false
      } else {
        seen.add(value)
        return true
      }
    })
  }

  function conversationPreviews(
    conversations: PrivateMessageView[],
  ): ConversationPreview[] {
    const deduplicated = filterDuplicates(conversations, (i) =>
      getOtherPartyId(i),
    )

    return deduplicated
      .filter((c) => c.creator.id != c.recipient.id) // you messaged yourself
      .map((i) => ({
        user:
          i.creator.id != profile.current.user?.local_user_view.person.id
            ? i.creator
            : i.recipient,
        message: {
          date: publishedToDate(i.private_message.published),
          last_sender: i.creator.id,
          content: i.private_message.content,
        },
      }))
  }

  let searchModal = $state<{ open: boolean; user?: number }>({
    open: false,
    user: undefined,
  })

  let { data } = $props()
</script>

<Modal bind:open={searchModal.open} title="Start chat">
  <UserAutocomplete
    listing_type="All"
    hideOwnUser={true}
    onselect={(u) => {
      if (!u) return
      goto(
        resolve('/inbox/messages/[user_id=integer]', {
          user_id: u.id.toString(),
        }),
      )
    }}
  />
</Modal>

{#snippet startChat()}
  <Button
    color="primary"
    size="lg"
    class="w-max"
    onclick={() => (searchModal.open = !searchModal.open)}
  >
    <Icon src={ChatBubbleOvalLeftEllipsis} size="18" mini />
    Start chat
  </Button>
{/snippet}

<Header pageHeader extended={startChat}>
  Messages
</Header>
{#await data.messages}
  <div class="w-full h-full flex flex-col gap-2">
    {#each new Array(5) as _, index}
      {_}
      <div
        in:fly|global={{
          duration: 1000,
          easing: expoOut,
          y: 12,
          delay: index * 50,
        }}
      >
        <Skeleton />
      </div>
    {/each}
  </div>
{:then res}
  {@const conversations = res.private_messages}
  {@const previews = conversationPreviews(conversations)}

  {#if previews.length == 0}
    <Placeholder
      title="No messages"
      icon={Inbox}
      class="my-auto"
    >
      {@render startChat?.()}
    </Placeholder>
  {/if}
  <CommonList items={previews}>
    {#snippet item(preview)}
      <a
        href="/inbox/messages/{preview.user.id}"
        class="flex flex-row items-center gap-2"
      >
        <Avatar url={preview.user.avatar} alt={preview.user.name} width={32} />
        <div class="flex flex-col w-full overflow-hidden">
          <div class="font-medium">{preview.user.name}</div>
          <div class="flex w-full">
            <div
              class="text-sm text-ellipsis whitespace-nowrap
            bg-linear-to-r from-slate-700 via-slate-700 to-slate-700/0 dark:from-zinc-300 dark:via-zinc-300 dark:to-zinc-300/0
            text-transparent bg-clip-text flex-1 overflow-hidden"
            >
              {#if preview.message.last_sender == profile.current.user?.local_user_view.person.id}
                {profile.current.user?.local_user_view.person.name}:
              {/if}
              {preview.message.content}
            </div>
            <RelativeDate
              date={preview.message.date}
              class="inline-block text-xs text-slate-600 dark:text-zinc-400 shrink-0"
            />
          </div>
        </div>
      </a>
    {/snippet}
  </CommonList>

  {#if res.private_messages.length == 50 || data.page != 1}
    <Fixate placement="bottom">
      <Pageination
        page={data.page}
        hasMore={res.private_messages.length == 50}
        href={(current) => `/inbox/messages?page=${current}`}
      />
    </Fixate>
  {/if}
{/await}
